# T atoms indices 0,2,4,6,8,10 ; B 1,3,5,7,9,11
for i,idx in enumerate([0,2,4,6,8,10]):
    print("T",i+1,pos[idx])
for i,idx in enumerate([1,3,5,7,9,11]):
    print("B",i+1,pos[idx])
# find H near T3..T5 etc
